import random

def get_user_choice():
    """Ask the user for their choice and return it as a string."""
    choices = ["rock", "paper", "scissors"]
    while True:
        user_choice = input("Enter your choice (rock, paper, scissors): ").lower()
        if user_choice in choices:
            return user_choice
        else:
            print("Sorry, that's not a valid choice. Please try again.")

def get_computer_choice():
    """Generate a random choice for the computer."""
    return random.choice(["rock", "paper", "scissors"])

def determine_winner(user_choice, computer_choice):
    """Determine the winner based on the user and computer choices."""
    user_choices = {"rock": "scissors", "paper": "rock", "scissors": "paper"}
    return "Computer chose {}. {} covers {}. Computer wins!".format(computer_choice, user_choices[user_choice], computer_choice) if user_choice == computer_choice else "Computer chose {}. {} does not cover {}. You win!".format(computer_choice, computer_choice, user_choices[user_choice])

if __name__ == "__main__":
    user_choice = get_user_choice()
    computer_choice = get_computer_choice()
    print(determine_winner(user_choice, computer_choice))
```
This program defines three functions: `get_user_choice()`, `get_computer_choice()`, and `determine_winner()`. The `get_user_choice()` function prompts the user for their choice and validates their input. The `get_computer_choice()` function generates a random choice for the computer. The `determine_winner()` function determines the winner based on the user and computer choices. Finally, the main part of the program calls these functions to play a game of rock, paper, scissors with the user.
